.root {
    -fx-font-family: "Space Grotesk", "Segoe UI", "Calibri", sans-serif;

    -pulse-bg0: #071422;
    -pulse-bg1: #0a1c2f;
    -pulse-glass: rgba(17, 48, 80, 0.45);
    -pulse-stroke: rgba(255, 255, 255, 0.12);
    -pulse-stroke-soft: rgba(255, 255, 255, 0.08);

    -pulse-text: #e9f2ff;
    -pulse-muted: rgba(233, 242, 255, 0.65);
    -pulse-muted2: rgba(233, 242, 255, 0.45);

    -pulse-green: #28ff8a;
    -pulse-green2: #1bd96f;
    -pulse-cyan: #2bd2ff;
    -pulse-yellow: #ffd24a;

    -pulse-radius: 18;
    -pulse-radius2: 22;

    -fx-text-fill: -pulse-text;
}

.app-root {
    -fx-background-color:
            radial-gradient(center 70% 10%, radius 120%, rgba(43, 210, 255, 0.17), transparent),
            radial-gradient(center 20% 40%, radius 90%, rgba(255, 210, 74, 0.08), transparent),
            linear-gradient(to bottom, -pulse-bg0, -pulse-bg1);
}

.top-wrapper {
    -fx-background-color: rgba(7, 20, 34, 0.78);
    -fx-border-color: rgba(255, 255, 255, 0.1);
    -fx-border-width: 0 0 1 0;
}

.heroTop {
    -fx-alignment: center-left;
}

.brand {
    -fx-padding: 0 6 0 0;
}

.brand__logoImg {
    -fx-border-color: rgba(40, 255, 138, 0.35);
    -fx-border-width: 1;
    -fx-background-radius: 14;
    -fx-border-radius: 14;
    -fx-effect: dropshadow(gaussian, rgba(40, 255, 138, 0.2), 16, 0.2, 0, 2);
}

.brand-main {
    -fx-font-size: 19px;
    -fx-font-weight: 900;
    -fx-letter-spacing: 0.08em;
    -fx-text-fill: rgba(233, 242, 255, 0.95);
}

.brand-sub {
    -fx-font-size: 12px;
    -fx-text-fill: -pulse-muted2;
}

.topbar {
    -fx-background-color: rgba(17, 48, 80, 0.4);
    -fx-border-color: rgba(255, 255, 255, 0.14);
    -fx-border-width: 1;
    -fx-border-radius: 22;
    -fx-background-radius: 22;
    -fx-padding: 8 10 8 10;
}

.topbar__item {
    -fx-background-color: rgba(255, 255, 255, 0.02);
    -fx-text-fill: rgba(233, 242, 255, 0.84);
    -fx-padding: 10 12 10 12;
    -fx-font-weight: 800;
    -fx-border-color: transparent;
    -fx-border-width: 1;
    -fx-border-radius: 16;
    -fx-background-radius: 16;
}

.topbar__item:hover {
    -fx-background-color: rgba(255, 255, 255, 0.08);
    -fx-border-color: rgba(255, 255, 255, 0.15);
}

.topbar__item--active {
    -fx-background-color: rgba(40, 255, 138, 0.16);
    -fx-border-color: rgba(40, 255, 138, 0.32);
    -fx-text-fill: rgba(233, 242, 255, 0.98);
}

.heroTop__right {
    -fx-alignment: center-right;
}

.signInBtn {
    -fx-background-color: rgba(17, 48, 80, 0.36);
    -fx-text-fill: rgba(233, 242, 255, 0.94);
    -fx-font-weight: 900;
    -fx-letter-spacing: 0.08em;
    -fx-padding: 10 14 10 14;
    -fx-border-color: rgba(40, 255, 138, 0.38);
    -fx-border-width: 1;
    -fx-border-radius: 999;
    -fx-background-radius: 999;
}

.signInBtn:hover {
    -fx-background-color: rgba(17, 48, 80, 0.52);
    -fx-border-color: rgba(40, 255, 138, 0.56);
}

.menuBtn {
    -fx-min-width: 44;
    -fx-pref-width: 44;
    -fx-min-height: 44;
    -fx-pref-height: 44;
    -fx-padding: 0;
    -fx-font-size: 10px;
    -fx-font-weight: 900;
    -fx-background-color: rgba(17, 48, 80, 0.36);
    -fx-text-fill: rgba(233, 242, 255, 0.9);
    -fx-border-color: rgba(255, 255, 255, 0.15);
    -fx-border-width: 1;
    -fx-border-radius: 16;
    -fx-background-radius: 16;
}

.menuBtn:hover {
    -fx-background-color: rgba(17, 48, 80, 0.52);
}

.page-title {
    -fx-font-size: 16px;
    -fx-font-weight: 900;
    -fx-letter-spacing: 0.05em;
    -fx-text-fill: rgba(233, 242, 255, 0.94);
}

.db-badge {
    -fx-font-size: 11px;
    -fx-text-fill: rgba(233, 242, 255, 0.9);
    -fx-background-color: rgba(43, 210, 255, 0.16);
    -fx-border-color: rgba(43, 210, 255, 0.32);
    -fx-border-width: 1;
    -fx-padding: 5 10 5 10;
    -fx-background-radius: 999;
    -fx-border-radius: 999;
}

.page-host {
    -fx-padding: 0;
}

.page-scroll,
.accountSidebarScroll {
    -fx-background-color: transparent;
    -fx-border-color: transparent;
}

.page-scroll > .viewport,
.accountSidebarScroll > .viewport {
    -fx-background-color: transparent;
}

.page-root {
    -fx-background-color: transparent;
}

.muted {
    -fx-text-fill: -pulse-muted;
}

.heroFull {
    -fx-background-color: rgba(255, 255, 255, 0.03);
    -fx-border-color: rgba(255, 255, 255, 0.12);
    -fx-border-width: 1;
    -fx-border-radius: 22;
    -fx-background-radius: 22;
    -fx-padding: 0;
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.34), 34, 0.2, 0, 8);
}

.heroFull__bg {
    -fx-background-position: center center;
    -fx-background-size: cover;
    -fx-background-repeat: no-repeat;
    -fx-opacity: 0.95;
    -fx-background-radius: 22 22 0 0;
}

.heroFull__overlay {
    -fx-background-color:
            radial-gradient(center 50% 38%, radius 75%, rgba(40, 255, 138, 0.16), transparent),
            linear-gradient(to bottom, rgba(6, 14, 26, 0.3), rgba(6, 14, 26, 0.74));
    -fx-background-radius: 22 22 0 0;
}

.heroCenter {
    -fx-padding: 28 24 42 24;
}

.heroKicker {
    -fx-font-size: 12px;
    -fx-font-weight: 900;
    -fx-letter-spacing: 0.18em;
    -fx-text-fill: rgba(233, 242, 255, 0.82);
}

.heroTitle {
    -fx-font-size: 74px;
    -fx-font-weight: bold;
    -fx-letter-spacing: 0.06em;
    -fx-text-fill: rgba(233, 242, 255, 0.97);
}

.heroSub {
    -fx-font-size: 14px;
    -fx-text-fill: rgba(233, 242, 255, 0.74);
}

.heroCtas {
    -fx-padding: 8 0 0 0;
}

.cta,
.cta-green,
.cta-glass {
    -fx-padding: 11 16 11 16;
    -fx-font-size: 11px;
    -fx-font-weight: 900;
    -fx-letter-spacing: 0.08em;
    -fx-border-radius: 999;
    -fx-background-radius: 999;
    -fx-border-color: rgba(255, 255, 255, 0.14);
    -fx-border-width: 1;
}

.cta--green,
.cta-green {
    -fx-background-color: linear-gradient(to bottom, rgba(40, 255, 138, 0.95), rgba(27, 217, 111, 0.82));
    -fx-text-fill: #04120a;
    -fx-border-color: rgba(40, 255, 138, 0.38);
}

.cta--glass,
.cta-glass {
    -fx-background-color: rgba(17, 48, 80, 0.36);
    -fx-text-fill: rgba(233, 242, 255, 0.92);
}

.heroWidgets {
    -fx-padding: 6 0 0 0;
}

.widget {
    -fx-min-width: 180;
    -fx-padding: 11 14 11 14;
    -fx-border-radius: 18;
    -fx-background-radius: 18;
    -fx-border-color: rgba(255, 255, 255, 0.14);
    -fx-border-width: 1;
    -fx-background-color: rgba(17, 48, 80, 0.35);
}

.widget__value {
    -fx-font-weight: bold;
    -fx-font-size: 20px;
    -fx-text-fill: rgba(233, 242, 255, 0.96);
}

.widget__label {
    -fx-font-size: 11px;
    -fx-text-fill: rgba(233, 242, 255, 0.68);
}

.heroSlash {
    -fx-background-color: linear-gradient(to right, rgba(40, 255, 138, 0.95), rgba(40, 255, 138, 0.4));
}

.belowHero {
    -fx-background-color: transparent;
}

.globalSearchWrap {
    -fx-padding: 8 0 0 0;
}

.globalSearch {
    -fx-padding: 10 12 10 12;
    -fx-border-color: rgba(255, 255, 255, 0.14);
    -fx-border-width: 1;
    -fx-border-radius: 999;
    -fx-background-radius: 999;
    -fx-background-color: rgba(17, 48, 80, 0.28);
}

.globalSearch__input {
    -fx-background-color: transparent;
    -fx-text-fill: rgba(233, 242, 255, 0.92);
    -fx-prompt-text-fill: rgba(233, 242, 255, 0.5);
    -fx-border-color: transparent;
    -fx-background-insets: 0;
    -fx-font-size: 14px;
}

.globalSearch__btn {
    -fx-background-color: rgba(40, 255, 138, 0.14);
    -fx-text-fill: rgba(233, 242, 255, 0.95);
    -fx-border-color: rgba(40, 255, 138, 0.3);
    -fx-border-width: 1;
    -fx-border-radius: 999;
    -fx-background-radius: 999;
    -fx-font-weight: 900;
    -fx-font-size: 11px;
}

.globalSearch__clear {
    -fx-background-color: rgba(255, 255, 255, 0.03);
    -fx-text-fill: rgba(233, 242, 255, 0.85);
    -fx-border-color: rgba(255, 255, 255, 0.14);
    -fx-border-width: 1;
    -fx-border-radius: 999;
    -fx-background-radius: 999;
}

.globalSearchHint {
    -fx-text-fill: rgba(233, 242, 255, 0.7);
    -fx-font-size: 12px;
}

.section {
    -fx-padding: 2 0 0 0;
}

.section-search,
.panel,
.heroMiniBox,
.hero-mini-box,
.side-nav-box {
    -fx-padding: 14;
    -fx-border-color: rgba(255, 255, 255, 0.1);
    -fx-border-width: 1;
    -fx-border-radius: 22;
    -fx-background-radius: 22;
    -fx-background-color: rgba(255, 255, 255, 0.03);
    -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.25), 16, 0.18, 0, 3);
}

.panel:hover,
