    -fx-border-color: transparent;
    -fx-border-width: 1;
    -fx-border-radius: 16;
    -fx-background-radius: 16;
}

.topbar__item:hover {
    -fx-background-color: rgba(255, 255, 255, 0.08);
    -fx-border-color: rgba(255, 255, 255, 0.15);
}

.topbar__item--active {
    -fx-background-color: rgba(40, 255, 138, 0.16);
    -fx-border-color: rgba(40, 255, 138, 0.32);
    -fx-text-fill: rgba(233, 242, 255, 0.98);
}

.heroTop__right {
    -fx-alignment: center-right;
}

.signInBtn {
    -fx-background-color: rgba(17, 48, 80, 0.36);
    -fx-text-fill: rgba(233, 242, 255, 0.94);
    -fx-font-weight: 900;
    -fx-letter-spacing: 0.08em;
    -fx-padding: 10 14 10 14;
    -fx-border-color: rgba(40, 255, 138, 0.38);
    -fx-border-width: 1;
    -fx-border-radius: 999;
    -fx-background-radius: 999;
}

.signInBtn:hover {
    -fx-background-color: rgba(17, 48, 80, 0.52);
    -fx-border-color: rgba(40, 255, 138, 0.56);
}

.menuBtn {
    -fx-min-width: 44;
    -fx-pref-width: 44;
    -fx-min-height: 44;
    -fx-pref-height: 44;
