    -fx-font-size: 10px;
    -fx-font-weight: 900;
    -fx-background-color: rgba(17, 48, 80, 0.36);
    -fx-text-fill: rgba(233, 242, 255, 0.9);
    -fx-border-color: rgba(255, 255, 255, 0.15);
    -fx-border-width: 1;
    -fx-border-radius: 16;
    -fx-background-radius: 16;
}

.menuBtn:hover {
