    -fx-background-color: rgba(255, 255, 255, 0.04);
    -fx-border-color: rgba(255, 255, 255, 0.12);
    -fx-border-width: 1;
    -fx-border-radius: 14;
    -fx-background-radius: 14;
    -fx-text-fill: rgba(233, 242, 255, 0.92);
    -fx-prompt-text-fill: rgba(233, 242, 255, 0.5);
    -fx-padding: 10 12 10 12;
    -fx-control-inner-background: rgba(7, 20, 34, 0.68);
    -fx-highlight-fill: rgba(43, 210, 255, 0.36);
    -fx-highlight-text-fill: rgba(233, 242, 255, 0.98);
}

.text-area .content,
.textarea .content {
    -fx-background-color: rgba(7, 20, 34, 0.68);
    -fx-background-insets: 0;
    -fx-background-radius: 12;
}

.text-area .text,
.textarea .text {
    -fx-fill: rgba(233, 242, 255, 0.96);
}

.text-area .prompt-text,
.textarea .prompt-text {
    -fx-fill: rgba(233, 242, 255, 0.5);
}

.listItem,
.list-item {
    -fx-alignment: center-left;
    -fx-padding: 10 12 10 12;
    -fx-border-color: rgba(255, 255, 255, 0.1);
    -fx-border-width: 1;
    -fx-border-radius: 16;
    -fx-background-radius: 16;
    -fx-background-color: rgba(255, 255, 255, 0.02);
}

.listItem__meta,
.list-item-meta {
    -fx-text-fill: -pulse-muted;
    -fx-font-size: 12px;
}

.badge {
    -fx-padding: 6 10 6 10;
    -fx-border-radius: 999;
    -fx-background-radius: 999;
    -fx-border-width: 1;
    -fx-font-size: 11px;
}

.badge-success {
    -fx-background-color: rgba(40, 255, 138, 0.14);
    -fx-border-color: rgba(40, 255, 138, 0.35);
    -fx-text-fill: rgba(233, 242, 255, 0.94);
}

.badge-warning {
    -fx-background-color: rgba(255, 210, 74, 0.12);
    -fx-border-color: rgba(255, 210, 74, 0.35);
    -fx-text-fill: #1c1400;
}

.badge-info {
    -fx-background-color: rgba(43, 210, 255, 0.14);
    -fx-border-color: rgba(43, 210, 255, 0.34);
    -fx-text-fill: rgba(233, 242, 255, 0.94);
}

.badge-danger {
    -fx-background-color: rgba(255, 120, 120, 0.12);
    -fx-border-color: rgba(255, 120, 120, 0.35);
    -fx-text-fill: rgba(233, 242, 255, 0.94);
}

.tabs {
    -fx-alignment: center-left;
}

.tab {
    -fx-background-color: rgba(255, 255, 255, 0.03);
    -fx-border-color: rgba(255, 255, 255, 0.12);
    -fx-border-width: 1;
    -fx-border-radius: 999;
    -fx-background-radius: 999;
    -fx-padding: 8 12 8 12;
    -fx-font-size: 12px;
    -fx-font-weight: 700;
    -fx-text-fill: rgba(233, 242, 255, 0.92);
}

.tab--active,
.tab.is-active {
    -fx-background-color: rgba(40, 255, 138, 0.14);
    -fx-border-color: rgba(40, 255, 138, 0.3);
}

.emptyState,
.empty-state {
    -fx-padding: 18;
    -fx-border-color: rgba(255, 255, 255, 0.14);
    -fx-border-style: dashed;
    -fx-border-radius: 18;
    -fx-background-radius: 18;
    -fx-text-fill: -pulse-muted;
    -fx-alignment: center;
}

.post-image-preview {
    -fx-background-radius: 18;
    -fx-border-radius: 18;
    -fx-border-color: rgba(255, 255, 255, 0.12);
    -fx-border-width: 1;
}

.admin-users-bar-item {
    -fx-padding: 4 0 4 0;
}

.admin-users-progress {
    -fx-pref-height: 10;
}

.admin-users-progress > .track {
    -fx-background-color: rgba(255, 255, 255, 0.12);
    -fx-background-radius: 999;
}

.admin-users-progress > .bar {
    -fx-background-color: linear-gradient(to right, rgba(40, 255, 138, 0.9), rgba(43, 210, 255, 0.9));
    -fx-background-radius: 999;
}

.captain-side-nav {
    -fx-background-color:
            radial-gradient(center 85% 15%, radius 90%, rgba(43, 210, 255, 0.16), transparent),
            rgba(255, 255, 255, 0.03);
}

.captain-side-nav .button {
    -fx-alignment: center-left;
}

.captain-hero-panel {
    -fx-background-color:
            radial-gradient(center 80% 22%, radius 120%, rgba(43, 210, 255, 0.16), transparent),
            linear-gradient(to bottom, rgba(8, 25, 43, 0.92), rgba(7, 21, 37, 0.92));
    -fx-border-color: rgba(255, 255, 255, 0.14);
}

.team-card {
    -fx-border-color: rgba(255, 255, 255, 0.14);
}

.team-card .card__body {
    -fx-padding: 12 12 12 12;
}

.adminUsersStats {
    -fx-background-color:
            radial-gradient(center 88% 18%, radius 120%, rgba(43, 210, 255, 0.14), transparent),
            rgba(255, 255, 255, 0.03);
}

.combo-box .list-cell {
    -fx-text-fill: rgba(233, 242, 255, 0.94);
}

.combo-box .arrow-button {
    -fx-background-color: rgba(255, 255, 255, 0.06);
    -fx-background-radius: 10;
}

.combo-box-popup .list-view {
    -fx-background-color: rgba(9, 22, 38, 0.98);
    -fx-border-color: rgba(255, 255, 255, 0.14);
    -fx-border-width: 1;
}

.combo-box-popup .list-cell {
    -fx-background-color: transparent;
    -fx-text-fill: rgba(233, 242, 255, 0.9);
}

.combo-box-popup .list-cell:hover {
    -fx-background-color: rgba(43, 210, 255, 0.16);
}

.combo-box-popup .list-cell:selected {
    -fx-background-color: rgba(40, 255, 138, 0.2);
    -fx-text-fill: rgba(233, 242, 255, 0.98);
}

.chat-panel {
    -fx-spacing: 12;
}

.chat-panel .chat-scroll {
    -fx-border-color: rgba(255, 255, 255, 0.1);
    -fx-border-radius: 14;
    -fx-background-radius: 14;
    -fx-background-color: rgba(255, 255, 255, 0.02);
}

.chat-quick-actions {
    -fx-alignment: top-left;
    -fx-spacing: 8;
}

.chat-input-section {
    -fx-spacing: 8;
    -fx-padding: 0;
}

.chat-scroll {
    -fx-min-height: 340;
    -fx-pref-height: 420;
    -fx-background-color: transparent;
    -fx-border-color: transparent;
}

.chat-scroll > .viewport {
    -fx-background-color: transparent;
}

.chat-history {
    -fx-padding: 4 2 4 2;
    -fx-spacing: 8;
}

.chat-line {
    -fx-padding: 0;
}

.chat-bubble {
    -fx-padding: 12 14 12 14;
    -fx-border-radius: 18;
    -fx-background-radius: 18;
    -fx-border-width: 1;
    -fx-min-height: region;
}

.chat-bubble--assistant {
    -fx-background-color: rgba(255, 255, 255, 0.04);
    -fx-border-color: rgba(255, 255, 255, 0.12);
    -fx-text-fill: rgba(233, 242, 255, 0.96);
}

.chat-bubble--user {
    -fx-background-color: rgba(40, 255, 138, 0.12);
    -fx-border-color: rgba(40, 255, 138, 0.28);
    -fx-text-fill: rgba(233, 242, 255, 0.96);
}

.chat-bubble__role {
    -fx-font-size: 10px;
    -fx-font-weight: bold;
    -fx-letter-spacing: 0.1em;
    -fx-text-fill: rgba(233, 242, 255, 0.72);
    -fx-text-alignment: left;
}

.chat-bubble__content {
    -fx-font-size: 13px;
    -fx-text-fill: rgba(233, 242, 255, 0.96);
    -fx-text-alignment: left;
    -fx-wrap-text: true;
}

.chat-input {
    -fx-pref-row-count: 3;
    -fx-min-height: 88;
}

.chatbot-floating-btn {
    -fx-min-width: 60;
    -fx-pref-width: 60;
    -fx-min-height: 60;
    -fx-pref-height: 60;
    -fx-padding: 0;
    -fx-font-size: 26px;
    -fx-font-weight: bold;
    -fx-background-color: linear-gradient(to bottom, rgba(40, 255, 138, 0.92), rgba(27, 217, 111, 0.82));
    -fx-text-fill: #04120a;
    -fx-border-color: rgba(40, 255, 138, 0.48);
    -fx-border-width: 2;
    -fx-border-radius: 999;
    -fx-background-radius: 999;
    -fx-cursor: hand;
    -fx-effect: dropshadow(gaussian, rgba(40, 255, 138, 0.44), 24, 0.22, 0, 6);
}

.chatbot-floating-btn:hover {
    -fx-background-color: linear-gradient(to bottom, rgba(40, 255, 138, 1.0), rgba(27, 217, 111, 0.92));
    -fx-border-color: rgba(40, 255, 138, 0.68);
    -fx-effect: dropshadow(gaussian, rgba(40, 255, 138, 0.62), 32, 0.26, 0, 8);
    -fx-scale-x: 1.08;
    -fx-scale-y: 1.08;
}

.chatbot-floating-btn:pressed {
    -fx-background-color: linear-gradient(to bottom, rgba(40, 255, 138, 0.85), rgba(27, 217, 111, 0.75));
    -fx-border-color: rgba(40, 255, 138, 0.52);
    -fx-effect: dropshadow(gaussian, rgba(40, 255, 138, 0.35), 18, 0.18, 0, 4);
}

.chatbot-popup-root {
    -fx-background-color: -pulse-bg1;
    -fx-border-color: rgba(255, 255, 255, 0.14);
    -fx-border-width: 1;
    -fx-border-radius: 18;
}

.chatbot-popup__header {
    -fx-padding: 0;
    -fx-border-color: rgba(255, 255, 255, 0.1);
    -fx-border-width: 0 0 1 0;
    -fx-padding: 0 0 10 0;
}

.chatbot-popup__title {
    -fx-font-size: 13px;
    -fx-font-weight: bold;
    -fx-text-fill: rgba(233, 242, 255, 0.96);
}

.chatbot-popup__close-btn {
     -fx-min-width: 28;
     -fx-pref-width: 28;
     -fx-min-height: 28;
     -fx-pref-height: 28;
     -fx-padding: 0;
     -fx-font-size: 18px;
     -fx-font-weight: 700;
     -fx-background-color: rgba(255, 255, 255, 0.05);
     -fx-text-fill: rgba(233, 242, 255, 0.8);
     -fx-border-color: transparent;
     -fx-border-radius: 8;
     -fx-background-radius: 8;
}

.chatbot-popup__close-btn:hover {
    -fx-background-color: rgba(255, 100, 100, 0.2);
    -fx-text-fill: rgba(233, 242, 255, 0.96);
}

.chatbot-popup__scroll {
    -fx-background-color: transparent;
    -fx-border-color: transparent;
}

.chatbot-popup__scroll > .viewport {
    -fx-background-color: transparent;
}

.chatbot-popup__history {
    -fx-padding: 8 4 8 4;
    -fx-background-color: transparent;
}

.chatbot-popup__line {
    -fx-padding: 0;
    -fx-background-color: transparent;
}

.chatbot-popup__bubble {
    -fx-padding: 10 12 10 12;
    -fx-border-radius: 14;
    -fx-background-radius: 14;
    -fx-border-width: 1;
}

.chatbot-popup__bubble--assistant {
    -fx-background-color: rgba(255, 255, 255, 0.08);
    -fx-border-color: rgba(255, 255, 255, 0.14);
}

.chatbot-popup__bubble--user {
    -fx-background-color: rgba(40, 255, 138, 0.18);
    -fx-border-color: rgba(40, 255, 138, 0.32);
}

.chatbot-popup__bubble-text {
    -fx-font-size: 12px;
    -fx-text-fill: rgba(233, 242, 255, 0.96);
    -fx-wrap-text: true;
}

.chatbot-popup__input-section {
    -fx-spacing: 6;
    -fx-padding: 10 0 0 0;
    -fx-border-color: rgba(255, 255, 255, 0.1);
    -fx-border-width: 1 0 0 0;
}

.chatbot-popup__input {
    -fx-control-inner-background: rgba(255, 255, 255, 0.04);
    -fx-pref-row-count: 2;
    -fx-min-height: 60;
    -fx-max-height: 100;
}

.chatbot-popup__input .content {
    -fx-background-color: rgba(7, 20, 34, 0.68);
    -fx-padding: 8;
}
